import os
import re
from collections import defaultdict

REPO = "/bench/repo"
STORE_PREFIX = os.path.join(REPO, "store")

# Persistent entity types (table-backed domain models from driver.go + store/*.go)
ENTITIES = [
    "Attachment", "Memo", "MemoRelation", "InstanceSetting", "User",
    "UserSetting", "IdentityProvider", "Inbox", "Reaction", "MemoShare", "UserIdentity",
]

def is_in_store_layer(filepath):
    rel = os.path.relpath(filepath, REPO)
    # Data layer: store/ tree (including store/db/*, store/cache, store/test)
    # Also proto/store and proto/gen/store are storage protos but entity Go types live in store/
    return rel.startswith("store" + os.sep) or rel == "store"

def package_dir(filepath):
    return os.path.dirname(filepath)

def find_go_files_outside_store():
    files = []
    for root, dirs, filenames in os.walk(REPO):
        # skip .git
        if '.git' in root.split(os.sep):
            continue
        for fn in filenames:
            if fn.endswith('.go'):
                fp = os.path.join(root, fn)
                if not is_in_store_layer(fp):
                    files.append(fp)
    return files

# Patterns for referencing store.EntityName
def entity_patterns(entity):
    return [
        re.compile(r'\bstore\.' + entity + r'\b'),
        re.compile(r'\[\]\*store\.' + entity + r'\b'),
        re.compile(r'\*store\.' + entity + r'\b'),
    ]

files = find_go_files_outside_store()
entity_packages = {e: set() for e in ENTITIES}
entity_files = {e: defaultdict(list) for e in ENTITIES}

for fp in files:
    try:
        content = open(fp, encoding='utf-8').errors('replace').read()
    except Exception:
        continue
    pkg = package_dir(fp)
    for entity in ENTITIES:
        matched = False
        for pat in entity_patterns(entity):
            if pat.search(content):
                matched = True
                break
        if matched:
            entity_packages[entity].add(pkg)
            entity_files[entity][pkg].append(os.path.relpath(fp, REPO))

# Sort by count
ranked = sorted(ENTITIES, key=lambda e: (-len(entity_packages[e]), e))
print("=== RANKING (distinct external Go package dirs) ===")
for e in ranked:
    pkgs = sorted(entity_packages[e])
    print(f"{e:20s} {len(pkgs):3d} packages")
    for p in pkgs:
        rel = os.path.relpath(p, REPO)
        print(f"    {rel} ({len(entity_files[e][p])} files)")

print(f"\nTotal external Go files scanned: {len(files)}")
print(f"Total distinct external packages importing store (any): ", end="")
store_import_pkgs = set()
for fp in files:
    content = open(fp, encoding='utf-8', errors='replace').read()
    if 'github.com/usememos/memos/store' in content or re.search(r'\bstore\.', content):
        if 'github.com/usememos/memos/store' in content:
            store_import_pkgs.add(package_dir(fp))
print(len(store_import_pkgs))
PYEOF

