perl -e '
use strict; use warnings;
my @entities = qw(Attachment Memo MemoRelation InstanceSetting User UserSetting IdentityProvider Inbox Reaction MemoShare UserIdentity);
my %pkg_count; my %pkg_list; my %file_list;
my @files = `find /bench/repo -name "*.go" ! -path "/bench/repo/store/*" ! -path "/bench/repo/.git/*" 2>/dev/null`;
chomp @files;
for my $f (@files) {
  open my $fh, "<", $f or next;
  my $content = do { local $/; <$fh> };
  close $fh;
  my $pkg = $f; $pkg =~ s/\/[^\/]+$//;
  for my $e (@entities) {
    if ($content =~ /\bstore\.$e\b/) {
      $pkg_count{$e}{$pkg} = 1;
      push @{$file_list{$e}{$pkg}}, $f;
    }
  }
}
print "=== RANKING ===\n";
my @ranked = sort { (scalar(keys %{$pkg_count{$b}}) <=> scalar(keys %{$pkg_count{$a}})) || $a cmp $b } @entities;
for my $e (@ranked) {
  my @pkgs = sort keys %{$pkg_count{$e}};
  print sprintf("%-20s %3d packages\n", $e, scalar @pkgs);
  for my $p (@pkgs) {
    my $rel = $p; $rel =~ s|^/bench/repo/||;
    my $fc = scalar @{$file_list{$e}{$p}};
    print "    $rel ($fc files)\n";
  }
}
print "\nTotal external go files: ", scalar(@files), "\n";
'

