perl -e '
use strict; use warnings;
my @entities = qw(Attachment Memo MemoRelation InstanceSetting User UserSetting IdentityProvider Inbox Reaction MemoShare UserIdentity);
my %is_data_layer;
for my $p (qw(store proto/store proto/gen/store)) {
  my @found = glob("/bench/repo/$p");
  for my $root (@found) {
    # mark all dirs under these roots
  }
}
sub in_data_layer {
  my ($f) = @_;
  return 1 if $f =~ m{^/bench/repo/store/} || $f eq "/bench/repo/store";
  return 1 if $f =~ m{^/bench/repo/proto/store/};
  return 1 if $f =~ m{^/bench/repo/proto/gen/store/};
  return 0;
}
sub pkg_dir { my ($f)=@_; $f =~ s/\/[^\/]+$//; return $f; }
my %counts; my %details;
my @files = `find /bench/repo -name "*.go" ! -path "/bench/repo/.git/*" 2>/dev/null`;
chomp @files;
for my $f (@files) {
  next if in_data_layer($f);
  open my $fh, "<", $f or next;
  my $content = do { local $/; <$fh> }; close $fh;
  my $has_store = ($content =~ /"github.com\/usememos\/memos\/store"/);
  my $has_storepb = ($content =~ /"github.com\/usememos\/memos\/proto\/gen\/store"/);
  next unless $has_store || $has_storepb;
  my $pkg = pkg_dir($f);
  my $rel = $f; $rel =~ s|^/bench/repo/||;
  for my $e (@entities) {
    my $hit = 0;
    $hit = 1 if $has_store && $content =~ /\bstore\.$e\b/;
    $hit = 1 if $has_storepb && $content =~ /\bstorepb\.$e\b/;
    if ($hit) {
      $counts{$e}{$pkg} = 1;
      push @{$details{$e}{$pkg}}, $rel;
    }
  }
}
print "=== COMBINED store.* + storepb.* references (excluding data layer) ===\n";
my @ranked = sort { (scalar(keys %{$counts{$b}}) <=> scalar(keys %{$counts{$a}})) || $a cmp $b } @entities;
for my $e (@ranked) {
  my @pkgs = sort keys %{$counts{$e}};
  print sprintf("%-20s %3d packages\n", $e, scalar @pkgs);
  for my $p (@pkgs) {
    my $rel = $p; $rel =~ s|^/bench/repo/||;
    print "    $rel (" . scalar(@{$details{$e}{$p}}) . " files)\n";
  }
}
'

